const T8_RW_M1: SatQuestion[] = [
  { id: "t8rw1-1", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The diplomat's remarks were carefully ______, designed to soothe both sides without committing to either position.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["measured", "reckless", "hostile", "spontaneous"], correct: 0, explanation: "Soothing both sides without committing requires \"measured\" (careful, restrained)." },
  { id: "t8rw1-2", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The flock of geese ______ across the gray autumn sky every morning.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["fly", "flies", "have flown", "are flying"], correct: 1, explanation: "The subject is singular \"flock,\" so the singular verb \"flies\" is correct." },
  { id: "t8rw1-3", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Octopuses can change both the color and texture of their skin in under a second, blending into coral, sand, or rock to evade predators.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Octopuses rapidly alter their skin to camouflage themselves.", "Octopuses can only change color, never texture.", "Octopuses are easily spotted by predators.", "Octopuses take hours to blend into their surroundings."], correct: 0, explanation: "The text describes near-instant color and texture changes used to blend in (choice A)." },
  { id: "t8rw1-4", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The bridge had stood for over a century. ______, engineers recommended a full inspection before reopening it to traffic.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Even so", "For instance", "Likewise", "In short"], correct: 0, explanation: "Despite its long endurance, inspection is still urged — a concession marked by \"Even so.\"" },
  { id: "t8rw1-5", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The expedition packed only the essentials ______ rope, a tent, and a week of rations.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["essentials, rope", "essentials: rope", "essentials; rope", "essentials rope"], correct: 1, explanation: "A colon introduces the list that specifies the \"essentials.\"" },
  { id: "t8rw1-6", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Her early sketches were merely ______, rough outlines she would later develop into finished paintings.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["preliminary", "definitive", "polished", "final"], correct: 0, explanation: "Rough outlines developed later are \"preliminary.\"" },
  { id: "t8rw1-7", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The grant funds research proposals submitted by faculty only; proposals from undergraduate students are not eligible.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A proposal written by an undergraduate cannot receive the grant.", "Only undergraduates may apply for the grant.", "Every proposal submitted is automatically funded.", "Faculty are barred from applying."], correct: 0, explanation: "Undergraduate proposals are not eligible, so they cannot receive the grant (choice A)." },
  { id: "t8rw1-8", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The startup doubled its revenue this year. ______, it cut its operating costs by nearly a third.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nevertheless", "At the same time", "In contrast", "Otherwise"], correct: 1, explanation: "A second favorable development is added alongside the first — \"At the same time.\"" },
  { id: "t8rw1-9", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "Each of the volunteers ______ asked to bring a signed permission form to the orientation.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["were", "are", "was", "have been"], correct: 2, explanation: "\"Each\" is singular and takes the singular verb \"was.\"" },
  { id: "t8rw1-10", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The senator's speech was praised for its ______ tone, treating opponents with unexpected courtesy.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["gracious", "scornful", "indifferent", "aggressive"], correct: 0, explanation: "Treating opponents with courtesy is \"gracious.\"" },
  { id: "t8rw1-11", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "A survey found that residents who walked to work reported higher satisfaction with their commute than those who drove, even when their travel times were similar.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["Walking commuters reported greater satisfaction than driving commuters of comparable commute length.", "Driving was always faster than walking.", "Commute time was the only factor that mattered.", "All residents preferred to drive."], correct: 0, explanation: "Even at similar times, walkers reported higher satisfaction (choice A)." },
  { id: "t8rw1-12", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The recipe calls for fresh basil. ______, dried basil may be substituted in a pinch.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Consequently", "Indeed"], correct: 1, explanation: "An alternative that contrasts with the ideal ingredient takes \"However.\"" },
  { id: "t8rw1-13", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The museum, which opened in 1899 ______ still attracts thousands of visitors each week.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["1899 still", "1899, still", "1899; still", "1899: still"], correct: 1, explanation: "A nonrestrictive clause closes with a comma before the main verb resumes." },
  { id: "t8rw1-14", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The river's ______ course made navigation difficult, winding back on itself again and again.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["meandering", "straight", "direct", "narrow"], correct: 0, explanation: "Winding back on itself describes a \"meandering\" course." },
  { id: "t8rw1-15", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Researchers noted that coral reefs recover faster when nearby fish populations remain large, because the fish graze on algae that would otherwise smother new coral.", prompt: "Which choice best states the main idea of the text?", type: "mcq", choices: ["Healthy fish populations aid reef recovery by controlling algae.", "Fish destroy coral reefs by eating them.", "Algae help coral grow more quickly.", "Reefs recover regardless of fish."], correct: 0, explanation: "Fish graze the algae that would smother coral, helping recovery (choice A)." },
  { id: "t8rw1-16", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The factory installed new filters to reduce pollution. ______, complaints from neighbors about air quality dropped sharply.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Nonetheless", "As a result", "In contrast", "For example"], correct: 1, explanation: "The drop in complaints follows from the new filters — cause and effect, \"As a result.\"" },
  { id: "t8rw1-17", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "By the time the rescue team arrived, the hikers ______ already found their way back to the trailhead.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["have", "had", "has", "will have"], correct: 1, explanation: "An action completed before another past event takes the past perfect \"had.\"" },
  { id: "t8rw1-18", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The professor's lectures were notoriously ______, packing three textbooks' worth of material into a single hour.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["dense", "sparse", "leisurely", "shallow"], correct: 0, explanation: "Packing in a huge amount of material makes the lectures \"dense.\"" },
  { id: "t8rw1-19", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "The new policy applies to part-time employees who have worked at least six months; those hired more recently are not yet covered.", prompt: "Which statement is best supported by the text?", type: "mcq", choices: ["A part-time worker hired last week is not yet covered by the policy.", "All part-time workers are immediately covered.", "Only full-time workers are covered.", "Workers of seven months are excluded."], correct: 0, explanation: "Fewer than six months means not yet covered, so a brand-new hire is excluded (choice A)." },
  { id: "t8rw1-20", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The trail map was outdated and confusing. ______, many visitors got lost on their way to the falls.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Even so", "Consequently", "By contrast", "For instance"], correct: 1, explanation: "Getting lost results from the bad map — \"Consequently.\"" },
  { id: "t8rw1-21", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The chef seasoned the soup, plated the dish, and ______ it to the waiting table.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["carrying", "carries", "carried", "to carry"], correct: 2, explanation: "Parallel with \"seasoned\" and \"plated\" requires the past-tense \"carried.\"" },
  { id: "t8rw1-22", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "Walking through the gallery, ______ caught the visitor's eye immediately.", prompt: "Which choice avoids a dangling modifier?", type: "mcq", choices: ["the bright mural", "the visitor saw the bright mural that", "there was a bright mural that", "a bright mural"], correct: 1, explanation: "The introductory phrase must describe \"the visitor,\" so the visitor must be the subject (choice B)." },
  { id: "t8rw1-23", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Although she had trained for the marathon for months, the runner approached the starting line with a calm she had not expected to feel.", prompt: "Which choice best describes the runner's state at the starting line?", type: "mcq", choices: ["surprisingly composed", "deeply anxious", "wholly unprepared", "openly fearful"], correct: 0, explanation: "She felt an unexpected \"calm\" — surprisingly composed (choice A)." },
  { id: "t8rw1-24", section: "rw", domain: "Expression of Ideas", difficulty: "med", passage: "The committee debated the proposal for hours. ______, no final decision was reached that evening.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "In the end", "For example", "Similarly"], correct: 1, explanation: "Summarizing the outcome of a long debate calls for \"In the end.\"" },
  { id: "t8rw1-25", section: "rw", domain: "Standard English Conventions", difficulty: "med", passage: "The two scientists shared the prize, but ______ contributions were quite different in nature.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["there", "their", "they're", "its"], correct: 1, explanation: "The plural possessive \"their\" modifies \"contributions.\"" },
  { id: "t8rw1-26", section: "rw", domain: "Craft and Structure", difficulty: "med", passage: "The editorial's argument rested on a single ______ assumption: that readers already agreed with its conclusion.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unexamined", "proven", "trivial", "shared"], correct: 0, explanation: "Resting on an assumption that simply presumes agreement makes it \"unexamined.\"" },
  { id: "t8rw1-27", section: "rw", domain: "Information and Ideas", difficulty: "med", passage: "Whereas the older textbook presents history as a list of dates, this edition organizes events around the people who shaped them.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To contrast two textbooks' approaches to organizing history.", "To argue that dates do not matter at all.", "To summarize the older textbook with approval.", "To list the events covered in the new edition."], correct: 0, explanation: "\"Whereas … this edition …\" contrasts a date-based and a people-centered approach (choice A)." },
];

