const T8_RW_M2H: SatQuestion[] = [
  { id: "t8rw2h-1", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The critic's praise was so ______ that readers struggled to tell whether she admired the book or quietly disdained it.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["equivocal", "effusive", "blunt", "scathing"], correct: 0, explanation: "Praise that hides its true stance is \"equivocal\" (ambiguous)." },
  { id: "t8rw2h-2", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The essay opens with an anecdote that seems trivial, but by its close the author has revealed the anecdote to embody her entire thesis.", prompt: "Which choice best describes the function of the opening anecdote?", type: "mcq", choices: ["It appears minor but ultimately illustrates the essay's central claim.", "It states the essay's conclusion outright.", "It contradicts the author's thesis.", "It serves only as decoration with no later relevance."], correct: 0, explanation: "The seemingly trivial anecdote turns out to embody the thesis (choice A)." },
  { id: "t8rw2h-3", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "A study measured plant growth under different light colors: 12 cm under red light, 19 cm under blue light, and 20 cm under combined red-and-blue light.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["Most of the growth benefit was achieved by blue light alone.", "Red light produced the tallest plants.", "Combined light cut growth in half.", "Light color made no difference to growth."], correct: 0, explanation: "Blue (19 cm) nearly matches combined (20 cm); the jump from red to blue is large while blue to combined is tiny (choice A)." },
  { id: "t8rw2h-4", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The treaty resolved the immediate border dispute. ______, it left untouched the deeper resentments that had fueled the conflict for decades.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "However", "Likewise", "Accordingly"], correct: 1, explanation: "Solving the surface issue but not the deeper one is a contrast — \"However.\"" },
  { id: "t8rw2h-5", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The internship offers students the chance to conduct research, to present findings, and ______ with industry experts.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["networking", "to network", "networks", "networked"], correct: 1, explanation: "Parallel with \"to conduct\" and \"to present\" requires \"to network.\"" },
  { id: "t8rw2h-6", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Far from being ______, the author's prose is dense with allusion, demanding careful rereading on every page.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["accessible", "intricate", "demanding", "layered"], correct: 0, explanation: "\"Far from being ___\" contrasts with the dense, demanding prose, so the blank means its opposite: \"accessible.\"" },
  { id: "t8rw2h-7", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "While earlier economists treated rising prices as a sign of prosperity, the author argues that the same trend can mask deepening inequality.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To challenge an earlier view by reinterpreting the same economic trend.", "To agree fully with earlier economists.", "To define the term inflation.", "To deny that prices ever rise."], correct: 0, explanation: "The author reinterprets the same trend against the earlier view (choice A)." },
  { id: "t8rw2h-8", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Neither the lead researcher nor her assistants ______ aware that the samples had been mislabeled.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "has been"], correct: 1, explanation: "With \"neither … nor,\" the verb agrees with the nearer subject — plural \"assistants\" — so \"were.\"" },
  { id: "t8rw2h-9", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The negotiator's ______ tone — never rising, never yielding — wore down the opposition over the long session.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["unrelenting", "erratic", "timid", "fleeting"], correct: 0, explanation: "Never rising, never yielding describes an \"unrelenting\" tone." },
  { id: "t8rw2h-10", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The historian cautions that surviving records favor the powerful, since the poor rarely left written accounts of their own.", prompt: "Which choice best states the historian's point?", type: "mcq", choices: ["The written record is skewed toward the powerful.", "The poor wrote most surviving documents.", "All social classes are equally documented.", "Written records are entirely reliable."], correct: 0, explanation: "Records favor the powerful because the poor seldom wrote (choice A)." },
  { id: "t8rw2h-11", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The vaccine proved effective in trials. ______, distributing it to remote regions posed logistical challenges no one had fully anticipated.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Hence", "Still", "Therefore", "Likewise"], correct: 1, explanation: "Success followed by an unforeseen obstacle is a contrast — \"Still.\"" },
  { id: "t8rw2h-12", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The director, along with the entire cast, ______ thanked the audience after the final performance.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["have", "were", "has", "having"], correct: 2, explanation: "The subject is singular \"director\"; the phrase \"along with the entire cast\" doesn't change agreement, so \"has.\"" },
  { id: "t8rw2h-13", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The poem's imagery is deliberately ______, refusing any single interpretation and inviting endless debate.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["polyvalent", "literal", "transparent", "simplistic"], correct: 0, explanation: "Imagery open to many readings is \"polyvalent\" (many-valued)." },
  { id: "t8rw2h-14", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "In a memory test, participants recalled 8 of 20 items with no review, 15 with one review, and 16 with two reviews.", prompt: "Which statement is best supported by the data?", type: "mcq", choices: ["The first review produced by far the largest recall gain.", "Reviewing hurt recall.", "Two reviews doubled the recall of one review.", "Review had no effect on recall."], correct: 0, explanation: "8 to 15 (+7) dwarfs 15 to 16 (+1); the first review gives the biggest gain (choice A)." },
  { id: "t8rw2h-15", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The new law promised sweeping reform. ______, its narrow definitions left most affected workers outside its protections.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["In practice", "Therefore", "Likewise", "As a result"], correct: 0, explanation: "Contrasting a promise with what actually happened takes \"In practice.\"" },
  { id: "t8rw2h-16", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The data ______ collected over three years, but the analysis took only a few months to complete.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["was", "were", "is", "are"], correct: 1, explanation: "Treated as plural in formal usage, \"data\" pairs with the past-tense \"were,\" consistent with the narrative." },
  { id: "t8rw2h-17", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The reviewer admired the building's ______ design, in which every ornament served a structural purpose.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["economical", "ostentatious", "haphazard", "cluttered"], correct: 0, explanation: "Nothing wasted — every ornament functional — is an \"economical\" design." },
  { id: "t8rw2h-18", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The author concedes that her model oversimplifies, yet maintains that its predictions match the data better than any rival.", prompt: "Which choice best describes the author's stance?", type: "mcq", choices: ["She defends the model's usefulness despite acknowledging its limits.", "She rejects the model entirely.", "She claims the model is flawless.", "She refuses to compare it with rivals."], correct: 0, explanation: "She admits a limit but still defends the model's predictive value (choice A)." },
  { id: "t8rw2h-19", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The renovation preserved the building's historic facade. ______, its interior was rebuilt entirely with modern materials.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Therefore", "Inside, by contrast,", "Likewise,", "As a result,"], correct: 1, explanation: "The contrast between preserved exterior and rebuilt interior is marked by \"by contrast.\"" },
  { id: "t8rw2h-20", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The startup's founders, ______ had met in college, built their first product in a rented garage.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["who", "whom", "which", "whose"], correct: 0, explanation: "The relative pronoun is the subject of \"had met,\" so the subject form \"who\" is correct." },
  { id: "t8rw2h-21", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "Rather than resolving the mystery, the final chapter ______ it, raising new questions in place of answers.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["compounds", "dispels", "clarifies", "simplifies"], correct: 0, explanation: "Raising new questions instead of answering means it \"compounds\" the mystery." },
  { id: "t8rw2h-22", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "Unlike accounts that credit the invention to a lone genius, this biography stresses the network of collaborators whose ideas made the breakthrough possible.", prompt: "Which choice best describes the main purpose of the text?", type: "mcq", choices: ["To reframe an invention as a collaborative achievement rather than a solo one.", "To name the single inventor responsible.", "To dismiss the breakthrough as unimportant.", "To praise lone-genius accounts."], correct: 0, explanation: "It contrasts a lone-genius story with a collaborative one (choice A)." },
  { id: "t8rw2h-23", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "The first engine stalled repeatedly ______ the redesigned model ran smoothly through every trial.", prompt: "Which choice conforms to the conventions of Standard English?", type: "mcq", choices: ["stalled repeatedly, the", "stalled repeatedly; the", "stalled repeatedly the", "stalled repeatedly: the"], correct: 1, explanation: "Two independent clauses are joined by a semicolon." },
  { id: "t8rw2h-24", section: "rw", domain: "Expression of Ideas", difficulty: "hard", passage: "The expedition gathered abundant samples. ______, poor weather forced the team to abandon its planned second site.", prompt: "Which choice completes the text with the most logical transition?", type: "mcq", choices: ["Consequently", "Even so", "Likewise", "Therefore"], correct: 1, explanation: "A success followed by a setback despite it takes the concessive \"Even so.\"" },
  { id: "t8rw2h-25", section: "rw", domain: "Craft and Structure", difficulty: "hard", passage: "The memoir's tone is ______: the author mocks her younger self even as she defends the choices that self made.", prompt: "Which choice completes the text with the most logical and precise word?", type: "mcq", choices: ["self-aware", "naive", "bitter", "detached"], correct: 0, explanation: "Mocking and defending oneself at once reflects a \"self-aware\" tone." },
  { id: "t8rw2h-26", section: "rw", domain: "Information and Ideas", difficulty: "hard", passage: "The geologist notes that the rock layers nearer the surface are younger, since each new deposit settles atop the ones already there.", prompt: "Which choice best states the geologist's point?", type: "mcq", choices: ["Higher rock layers tend to be more recent than lower ones.", "Deeper layers are always the youngest.", "All rock layers form at the same time.", "Rock layers cannot be dated by depth."], correct: 0, explanation: "New deposits settle on top, so upper layers are younger (choice A)." },
  { id: "t8rw2h-27", section: "rw", domain: "Standard English Conventions", difficulty: "hard", passage: "Having reviewed every applicant's file, ______ a decision before the deadline.", prompt: "Which choice avoids a dangling modifier?", type: "mcq", choices: ["a decision was reached by the committee", "the committee reached", "there was a decision", "the deadline forced a decision"], correct: 1, explanation: "The modifier must describe the one who reviewed the files — \"the committee\" — so it should be the subject (choice B)." },
];

